1	/**
2	 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
3	 *
4	 * 圆形表盘使用更激进的内缩边距（~70px 水平/55px 垂直），
5	 * 确保内容不会被圆弧边缘裁切。
6	 * 同时提供字体缩放系数，解决圆形表盘"整体太小看不清"的问题。
7	 */
8	
9	var screenW = 0
10	var screenH = 0
11	var shapeCache = null
12	
13	function detectShape() {
14	  try {
15	    var info = undefined
16	    if (typeof globalThis !== "undefined" && globalThis.systemInfo) {
17	      info = globalThis.systemInfo
18	    } else if (typeof global !== "undefined" && global.systemInfo) {
19	      info = global.systemInfo
20	    }
21	    if (info) {
22	      screenW = info.screenWidth || 480
23	      screenH = info.screenHeight || 480
24	    } else {
25	      screenW = 480
26	      screenH = 480
27	    }
28	  } catch (e) {
29	    screenW = 480
30	    screenH = 480
31	  }
32	
33	  // 宽高比接近 1:1 判定为圆形
34	  var ratio = screenW / screenH
35	  var isRound = ratio > 0.9 && ratio < 1.1
36	
37	  shapeCache = {
38	    isRound: isRound,
39	    isSquare: !isRound,
40	    screenWidth: screenW,
41	    screenHeight: screenH
42	  }
43	  return shapeCache
44	}
45	
46	// ─── 形状检测 ──────────────────────────────────────────
47	
48	export function getScreenShape() {
49	  if (!shapeCache) { detectShape() }
50	  return shapeCache
51	}
52	
53	export function getScreenHeight() {
54	  return getScreenShape().screenHeight
55	}
56	
57	// ─── 安全区内边距 ────────────────────────────────────
58	
59	export function getSafePadding() {
60	  var shape = getScreenShape()
61	  if (shape.isRound) {
62	    // 圆形表盘：水平 65px 避开弧边；垂直 55px 保护首尾但释放高度
63	    return { top: 55, right: 65, bottom: 55, left: 65 }
64	  }
65	  return { top: 18, right: 18, bottom: 16, left: 18 }
66	}
67	
68	// ─── 内容 padding（更保守的圆形安全区） ──────────────
69	
70	export function getContentPadding() {
71	  var p = getSafePadding()
72	  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
73	}
74	
75	// ─── 圆角 ────────────────────────────────────────────
