### 五、动画系统（Apple Watch 风格）

#### 1. 页面切换动画
```javascript
// Apple Watch 风格的弹性滑动
function awSlideTransition(element, direction, callback) {
  var startX = direction === 'left' ? -120 : 120;
  var duration = 300; // 300ms
  var steps = 18; // 60fps
  var step = 0;

  var timer = setInterval(function() {
    step++;
    var progress = step / steps;
    // Apple Watch 弹性缓动
    var eased = 1 - Math.pow(1 - progress, 3);
    var currentX = startX * (1 - eased);

    element.style.transform = 'translateX(' + currentX + '%)';
    element.style.opacity = String(0.5 + 0.5 * eased);

    if (step >= steps) {
      clearInterval(timer);
      element.style.transform = 'translateX(0)';
      element.style.opacity = '1';
      if (callback) callback();
    }
  }, duration / steps);
}
```

#### 2. 数字滚动动画
```javascript
// Apple Watch 风格的数字滚动
function awAnimateValue(element, target, duration) {
  var start = parseInt(element.textContent) || 0;
  var diff = target - start;
  var steps = Math.ceil(duration / 16);
  var step = 0;

  var timer = setInterval(function() {
    step++;
    var progress = step / steps;
    // Apple Watch 缓动
    var eased = 1 - Math.pow(1 - progress, 4);
    var current = Math.round(start + diff * eased);
    element.textContent = String(current);

    if (step >= steps) {
      clearInterval(timer);
      element.textContent = String(target);
    }
  }, 16);
}
```

#### 3. 按钮点击反馈
```javascript
// Apple Watch 按钮按下效果
function awButtonPress(element) {
  element.style.transform = 'scale(0.95)';
  element.style.opacity = '0.8';
}

function awButtonRelease(element) {
  element.style.transform = 'scale(1)';
  element.style.opacity = '1';
}
```

