#### Apple Watch 圆形适配原则
- 内容居中
- 边缘留白充足
- 避免文字贴近圆弧

```javascript
// Apple Watch 圆形表盘安全区
function getAWRoundSafeZone(screenSize) {
  var radius = screenSize / 2;
  return {
    top: Math.round(radius * 0.18),    // 18%
    bottom: Math.round(radius * 0.18),
    left: Math.round(radius * 0.22),   // 22%（水平更宽）
    right: Math.round(radius * 0.22)
  };
}

// 计算安全区内边距
function getAWContentPadding(screenShape) {
  if (screenShape.isRound) {
    var safe = getAWRoundSafeZone(screenShape.screenWidth);
    return safe.top + 'px ' + safe.right + 'px ' + safe.bottom + 'px ' + safe.left + 'px';
  }
  // 方形手表
  return '16px 18px';
}
```

