/**
 * animation-utils.js — VelaGuard 动画工具库
 *
 * Apple Watch 风格的流畅动画效果
 * 使用 JavaScript 实现，兼容 OpenVela 环境
 */

// ─── 缓动函数 ──────────────────────────────────────────

/**
 * 缓动函数：easeOutCubic
 * 用于页面切换、元素出现等
 */
export function easeOutCubic(t) {
  return 1 - Math.pow(1 - t, 3)
}

/**
 * 缓动函数：easeOutQuart
 * 用于数字滚动、进度环等
 */
export function easeOutQuart(t) {
  return 1 - Math.pow(1 - t, 4)
}

/**
 * 缓动函数：easeInOutCubic
 * 用于平滑的双向动画
 */
export function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

/**
 * 缓动函数：easeOutBack
 * 用于弹性效果，如按钮点击
 */
export function easeOutBack(t) {
  var c1 = 1.70158
  var c3 = c1 + 1
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2)
}

// ─── 基础动画函数 ──────────────────────────────────────

/**
 * 通用动画函数
 * @param {Object} options - 动画配置
 * @param {Function} options.onFrame - 每帧回调，参数为 progress (0-1)
 * @param {number} options.duration - 动画时长（毫秒）
 * @param {Function} options.easing - 缓动函数
 * @param {Function} options.onComplete - 动画完成回调
 * @returns {Object} 控制对象 { stop, pause, resume }
 */
export function animate(options) {
  var duration = options.duration || 300
  var easing = options.easing || easeOutCubic
  var onFrame = options.onFrame
  var onComplete = options.onComplete

  var startTime = null
  var paused = false
  var pausedTime = 0
  var animationId = null

  function tick(timestamp) {
    if (paused) return

    if (!startTime) startTime = timestamp
    var elapsed = timestamp - startTime - pausedTime
    var progress = Math.min(elapsed / duration, 1)
    var easedProgress = easing(progress)

    if (onFrame) onFrame(easedProgress, progress)

    if (progress < 1) {
      animationId = requestAnimationFrame(tick)
    } else {
      if (onComplete) onComplete()
    }
  }

  animationId = requestAnimationFrame(tick)

  return {
    stop: function() {
      if (animationId) cancelAnimationFrame(animationId)
    },
    pause: function() {
      paused = true
    },
    resume: function() {
      paused = false
      startTime = performance.now()
      pausedTime = 0
      animationId = requestAnimationFrame(tick)
    }
  }
}

// ─── 页面切换动画 ──────────────────────────────────────

/**
 * Apple Watch 风格的页面滑动切换
 * @param {Object} element - 页面元素
 * @param {string} direction - 方向 'left' 或 'right'
 * @param {Function} callback - 完成回调
 */
export function slideTransition(element, direction, callback) {
  var startX = direction === 'left' ? -120 : 120
  var duration = 300

  animate({
    duration: duration,
    easing: easeOutCubic,
    onFrame: function(progress) {
      var currentX = startX * (1 - progress)
      var opacity = 0.5 + 0.5 * progress
      element.style.transform = 'translateX(' + currentX + '%)'
      element.style.opacity = String(opacity)
    },
    onComplete: function() {
      element.style.transform = 'translateX(0)'
      element.style.opacity = '1'
      if (callback) callback()
    }
  })
}

/**
 * 页面淡入效果
 * @param {Object} element - 页面元素
 * @param {Function} callback - 完成回调
 */
export function fadeIn(element, callback) {
  element.style.opacity = '0'

  animate({
    duration: 250,
    easing: easeOutCubic,
    onFrame: function(progress) {
      element.style.opacity = String(progress)
    },
    onComplete: function() {
      element.style.opacity = '1'
      if (callback) callback()
    }
  })
}

/**
 * 页面淡出效果
 * @param {Object} element - 页面元素
 * @param {Function} callback - 完成回调
 */
export function fadeOut(element, callback) {
  animate({
    duration: 200,
    easing: easeOutCubic,
    onFrame: function(progress) {
      element.style.opacity = String(1 - progress)
    },
    onComplete: function() {
      element.style.opacity = '0'
      if (callback) callback()
    }
  })
}

// ─── 数字动画 ──────────────────────────────────────────

/**
 * 数字递增/递减动画
 * @param {Object} element - 文字元素
 * @param {number} target - 目标数值
 * @param {Object} options - 配置选项
 */
export function animateNumber(element, target, options) {
  options = options || {}
  var duration = options.duration || 500
  var prefix = options.prefix || ''
  var suffix = options.suffix || ''
  var start = parseInt(element.textContent) || 0
  var diff = target - start

  animate({
    duration: duration,
    easing: easeOutQuart,
    onFrame: function(progress) {
      var current = Math.round(start + diff * progress)
      element.textContent = prefix + current + suffix
    }
  })
}

// ─── 进度环动画 ──────────────────────────────────────

/**
 * 圆形进度环动画
 * @param {Object} element - 进度环元素
 * @param {number} targetPercent - 目标百分比 (0-100)
 * @param {Object} options - 配置选项
 */
export function animateRing(element, targetPercent, options) {
  options = options || {}
  var duration = options.duration || 600
  var startRotation = options.startRotation || -90
  var targetRotation = startRotation + Math.round(targetPercent * 3.6)

  animate({
    duration: duration,
    easing: easeOutCubic,
    onFrame: function(progress) {
      var currentRotation = startRotation + (targetRotation - startRotation) * progress
      element.style.transform = 'rotate(' + currentRotation + 'deg)'
    }
  })
}

// ─── 按钮交互动画 ──────────────────────────────────────

/**
 * 按钮按下效果
 * @param {Object} element - 按钮元素
 */
export function buttonPress(element) {
  animate({
    duration: 100,
    easing: easeOutCubic,
    onFrame: function(progress) {
      var scale = 1 - 0.05 * progress
      var opacity = 1 - 0.2 * progress
      element.style.transform = 'scale(' + scale + ')'
      element.style.opacity = String(opacity)
    }
  })
}

/**
 * 按钮释放效果
 * @param {Object} element - 按钮元素
 */
export function buttonRelease(element) {
  animate({
    duration: 150,
    easing: easeOutBack,
    onFrame: function(progress) {
      var scale = 0.95 + 0.05 * progress
      element.style.transform = 'scale(' + scale + ')'
      element.style.opacity = String(0.8 + 0.2 * progress)
    },
    onComplete: function() {
      element.style.transform = 'scale(1)'
      element.style.opacity = '1'
    }
  })
}

// ─── 呼吸灯效果 ──────────────────────────────────────

/**
 * 呼吸灯动画（用于 SOS 按钮等）
 * @param {Object} element - 元素
 * @param {Object} options - 配置选项
 * @returns {Object} 控制对象 { stop }
 */
export function breathingLight(element, options) {
  options = options || {}
  var minOpacity = options.minOpacity || 0.6
  var maxOpacity = options.maxOpacity || 1.0
  var period = options.period || 1800

  var running = true
  var startTime = null

  function tick(timestamp) {
    if (!running) return

    if (!startTime) startTime = timestamp
    var elapsed = (timestamp - startTime) % period
    var progress = elapsed / period

    // 正弦波产生呼吸效果
    var sinProgress = Math.sin(progress * Math.PI)
    var opacity = minOpacity + (maxOpacity - minOpacity) * sinProgress
    element.style.opacity = String(opacity)

    requestAnimationFrame(tick)
  }

  requestAnimationFrame(tick)

  return {
    stop: function() {
      running = false
      element.style.opacity = '1'
    }
  }
}

// ─── 脉冲动画 ──────────────────────────────────────────

/**
 * 脉冲扩散效果（用于状态指示器）
 * @param {Object} element - 元素
 * @param {Object} options - 配置选项
 * @returns {Object} 控制对象 { stop }
 */
export function pulse(element, options) {
  options = options || {}
  var duration = options.duration || 1000
  var scale = options.scale || 1.5
  var running = true

  function tick() {
    if (!running) return

    animate({
      duration: duration,
      easing: easeOutCubic,
      onFrame: function(progress) {
        var currentScale = 1 + (scale - 1) * progress
        var opacity = 1 - progress
        element.style.transform = 'scale(' + currentScale + ')'
        element.style.opacity = String(opacity)
      },
      onComplete: function() {
        if (running) {
          element.style.transform = 'scale(1)'
          element.style.opacity = '1'
          setTimeout(tick, 100)
        }
      }
    })
  }

  tick()

  return {
    stop: function() {
      running = false
      element.style.transform = 'scale(1)'
      element.style.opacity = '1'
    }
  }
}

// ─── 延迟工具 ──────────────────────────────────────────

/**
 * Promise 风格的延迟
 * @param {number} ms - 延迟毫秒数
 * @returns {Promise}
 */
export function delay(ms) {
  return new Promise(function(resolve) {
    setTimeout(resolve, ms)
  })
}

/**
 * 执行动画序列
 * @param {Array} animations - 动画配置数组
 * @param {Function} callback - 完成回调
 */
export function sequence(animations, callback) {
  var index = 0

  function next() {
    if (index >= animations.length) {
      if (callback) callback()
      return
    }

    var anim = animations[index]
    index++

    if (anim.delay) {
      setTimeout(function() {
        animate({
          duration: anim.duration || 300,
          easing: anim.easing || easeOutCubic,
          onFrame: anim.onFrame,
          onComplete: next
        })
      }, anim.delay)
    } else {
      animate({
        duration: anim.duration || 300,
        easing: anim.easing || easeOutCubic,
        onFrame: anim.onFrame,
        onComplete: next
      })
    }
  }

  next()
}

/**
 * 执行并行动画
 * @param {Array} animations - 动画配置数组
 * @param {Function} callback - 完成回调
 */
export function parallel(animations, callback) {
  var completed = 0
  var total = animations.length

  if (total === 0) {
    if (callback) callback()
    return
  }

  animations.forEach(function(anim) {
    animate({
      duration: anim.duration || 300,
      easing: anim.easing || easeOutCubic,
      onFrame: anim.onFrame,
      onComplete: function() {
        completed++
        if (completed >= total && callback) callback()
      }
    })
  })
}

