/**
 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
 *
 * 圆形表盘使用更激进的内缩边距（~70px 水平/55px 垂直），
 * 确保内容不会被圆弧边缘裁切。
 * 同时提供字体缩放系数，解决圆形表盘"整体太小看不清"的问题。
 */

var screenW = 0
var screenH = 0
var shapeCache = null

function detectShape() {
  try {
    var info = undefined
    if (typeof globalThis !== "undefined" && globalThis.systemInfo) {
      info = globalThis.systemInfo
    } else if (typeof global !== "undefined" && global.systemInfo) {
      info = global.systemInfo
    }
    if (info) {
      screenW = info.screenWidth || 480
      screenH = info.screenHeight || 480
    } else {
      screenW = 480
      screenH = 480
    }
  } catch (e) {
    screenW = 480
    screenH = 480
  }

  // 宽高比接近 1:1 判定为圆形
  var ratio = screenW / screenH
  var isRound = ratio > 0.9 && ratio < 1.1

  shapeCache = {
    isRound: isRound,
    isSquare: !isRound,
    screenWidth: screenW,
    screenHeight: screenH
  }
  return shapeCache
}

// ─── 形状检测 ──────────────────────────────────────────

export function getScreenShape() {
  if (!shapeCache) { detectShape() }
  return shapeCache
}

export function getScreenHeight() {
  return getScreenShape().screenHeight
}

// ─── 安全区内边距 ────────────────────────────────────

export function getSafePadding() {
  var shape = getScreenShape()
  if (shape.isRound) {
    // 圆形表盘：水平 65px 避开弧边；垂直 55px 保护首尾但释放高度
    return { top: 55, right: 65, bottom: 55, left: 65 }
  }
  return { top: 18, right: 18, bottom: 16, left: 18 }
}

// ─── 内容 padding（更保守的圆形安全区） ──────────────

export function getContentPadding() {
  var p = getSafePadding()
