/**
 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
 *
 * Apple Watch 风格适配：
 * - 圆形表盘使用更精确的内缩边距
 * - 字体缩放更合理
 * - 圆角统一为 Apple Watch 标准
 */

var screenW = 0
var screenH = 0
var shapeCache = null

function detectShape() {
  try {
    var info = undefined
    if (typeof globalThis !== "undefined" && globalThis.systemInfo) {
      info = globalThis.systemInfo
    } else if (typeof global !== "undefined" && global.systemInfo) {
      info = global.systemInfo
    }
    if (info) {
      screenW = info.screenWidth || 466
      screenH = info.screenHeight || 466
    } else {
      screenW = 466
      screenH = 466
    }
  } catch (e) {
    screenW = 466
    screenH = 466
  }

  // 宽高比接近 1:1 判定为圆形
  var ratio = screenW / screenH
  var isRound = ratio > 0.9 && ratio < 1.1

  shapeCache = {
    isRound: isRound,
    isSquare: !isRound,
    screenWidth: screenW,
    screenHeight: screenH,
    radius: Math.round(screenW / 2)
  }
  return shapeCache
}

// ─── 形状检测 ──────────────────────────────────────────

export function getScreenShape() {
  if (!shapeCache) { detectShape() }
  return shapeCache
}

export function getScreenHeight() {
  return getScreenShape().screenHeight
}

export function getScreenWidth() {
  return getScreenShape().screenWidth
}

// ─── Apple Watch 风格安全区内边距 ──────────────────────

export function getSafePadding() {
  var shape = getScreenShape()
  if (shape.isRound) {
    // Apple Watch 风格：更精确的圆形安全区
    var radius = shape.radius
    return {
      top: Math.round(radius * 0.18),    // 18%
      bottom: Math.round(radius * 0.18),
      left: Math.round(radius * 0.22),   // 22%（水平更宽）
      right: Math.round(radius * 0.22)
    }
  }
  return { top: 16, right: 18, bottom: 16, left: 18 }
}

// ─── 内容 padding ──────────────────────────────────────

export function getContentPadding() {
  var p = getSafePadding()
  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
}

// ─── Apple Watch 风格圆角 ──────────────────────────────

export function getCardRadius() {
  // Apple Watch 标准圆角：22px
  return getScreenShape().isRound ? 28 : 22
}

export function getButtonRadius() {
  // Apple Watch 按钮圆角：22px
  return getScreenShape().isRound ? 26 : 22
}

// ─── 字体缩放 ──────────────────────────────────────────

export function getFontScale() {
  // Apple Watch 风格：圆形表盘字体稍大，但不过度放大
  return getScreenShape().isRound ? 1.15 : 1.0
}

export function fs(baseSize) {
  var scale = getFontScale()
  return Math.round(baseSize * scale)
}

// ─── 按钮高度 ──────────────────────────────────────────

export function getButtonHeight(base) {
  return getScreenShape().isRound ? Math.round(base * 1.1) : base
}

// ─── 布局检测 ──────────────────────────────────────────

export function useVerticalLayout() {
  return getScreenShape().isRound
}

// ─── 动态 padding 字符串 ──────────────────────────────

export function padStr() {
  var p = getSafePadding()
  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
}

// ─── 安全区数值 ────────────────────────────────────────

export function getSafePadTop() {
  return getSafePadding().top
}

export function getSafePadSide() {
  return getSafePadding().right
}

// ─── 装饰条宽度 ────────────────────────────────────────

export function getAccentBarWidth() {
  return getScreenShape().isRound ? 4 : 3
}

// ─── 环形进度条尺寸（Apple Watch 风格） ────────────────

export function getRingSize() {
  // Apple Watch 风格：更大的环
  return getScreenShape().isRound ? 72 : 64
}

export function getRingStroke() {
  // Apple Watch 风格：更粗的环（8px）
  return getScreenShape().isRound ? 8 : 7
}

// ─── Tab 指示条高度 ──────────────────────────────────

export function getTabIndicatorHeight() {
  return 3
}

// ─── Apple Watch 风格间距 ──────────────────────────────

export function getSpacing(size) {
  var base = {
    xs: 4,
    sm: 8,
    md: 12,
    lg: 16,
    xl: 20,
    xxl: 28
  }
  return base[size] || 12
}

// ─── 卡片内边距 ────────────────────────────────────────

export function getCardPadding() {
  return getScreenShape().isRound ? 16 : 14
}

// ─── 按钮内边距 ────────────────────────────────────────

export function getButtonPadding() {
  return getScreenShape().isRound ? 15 : 13
}
